const pickSubscriptionImage=async()=>{
  const picker=document.createElement('input');picker.type='file';picker.accept='image/png,image/jpeg';
  picker.onchange=()=>{
    const file=picker.files?.[0];if(!file)return;
    if(!['image/png','image/jpeg'].includes(file.type))return browserAlert('Unsupported image','Choose a PNG or JPEG image.');
    const reader=new FileReader();
    reader.onerror=()=>browserAlert('Image failed','Could not read the selected image.');
    reader.onload=()=>{
      const uri=String(reader.result||'');
      if(uri.length>2800000)return browserAlert('Image too large','Choose a smaller image (roughly 2 MB or less).');
      setForm(f=>({...f,image_uri:uri}));
    };
    reader.readAsDataURL(file);
  };
  picker.click();
};
