const exportPaymentCSV=()=>{try{const esc=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const csv='\uFEFF'+[['Service','Amount','Paid Date'],...payments.map(p=>[p.service_name,p.amount,p.paid_at])].map(row=>row.map(esc).join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='subtrack-payments.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){browserAlert('Export failed',e.message||String(e))}};
const exportData=async()=>{
  try{
    const [freshSubs,freshCats,freshPayments,freshPrefs]=await Promise.all([
      db.getAllAsync('SELECT * FROM subscriptions'),db.getAllAsync('SELECT * FROM categories'),
      db.getAllAsync('SELECT * FROM payments'),db.getAllAsync('SELECT * FROM preferences')
    ]);
    const freshPrices=await db.getAllAsync('SELECT * FROM price_history');const payload=JSON.stringify({version:1,price_history:freshPrices,subscriptions:freshSubs,categories:freshCats,payments:freshPayments,preferences:Object.fromEntries(freshPrefs.map(x=>[x.key,x.value]))},null,2);
    const blob=new Blob([payload],{type:'application/json'});
    const url=URL.createObjectURL(blob);
    const anchor=document.createElement('a');anchor.href=url;anchor.download='subtrack-backup.json';
    document.body.appendChild(anchor);anchor.click();anchor.remove();
    window.setTimeout(()=>URL.revokeObjectURL(url),1000);
  }catch(e){browserAlert('Export failed',e.message)}
};
const importData=async()=>{
  try{
    const picker=document.createElement('input');picker.type='file';picker.accept='.json,application/json';
    picker.onchange=async()=>{
      if(!picker.files?.length)return;
      try{
        const data=validateBackup(JSON.parse(await picker.files[0].text()));
        browserAlert('Restore backup?','This replaces your current subscriptions, categories, payment history and preferences.',[
          {text:'Cancel',style:'cancel'},
          {text:'Restore Backup',style:'destructive',onPress:async()=>{
            try{
              await db.withTransactionAsync(async()=>{

          await db.execAsync('DELETE FROM price_history; DELETE FROM payments; DELETE FROM subscriptions; DELETE FROM categories;');
          for(const c of data.categories)await db.runAsync('INSERT INTO categories(id,name,color,icon) VALUES(?,?,?,?)',c.id,c.name,c.color,c.icon);
          for(const s of data.subscriptions)await db.runAsync('INSERT INTO subscriptions(id,name,price,cycle,next_date,category_id,notes,status,image_uri,home_url,manage_url,trial_end,reminder_days) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',s.id,s.name,s.price,s.cycle,s.next_date,s.category_id,s.notes||'',s.status||'Active',s.image_uri||null,s.home_url||null,s.manage_url||null,s.trial_end||null,s.reminder_days||null);
          for(const p of data.payments)await db.runAsync('INSERT INTO payments(id,subscription_id,service_name,amount,paid_at) VALUES(?,?,?,?,?)',p.id,p.subscription_id,p.service_name,p.amount,p.paid_at);for(const h of (data.price_history||[]))await db.runAsync('INSERT INTO price_history(id,subscription_id,service_name,old_price,new_price,changed_at) VALUES(?,?,?,?,?,?)',h.id,h.subscription_id,h.service_name,h.old_price,h.new_price,h.changed_at);
          if(data.preferences&&typeof data.preferences==='object')for(const [key,value] of Object.entries(data.preferences))if(['string','number','boolean'].includes(typeof value))await db.runAsync('INSERT OR REPLACE INTO preferences(key,value) VALUES(?,?)',key,String(value));
              });
              await reload();tab('home');browserAlert('Restored','Your backup was restored.');
            }catch(e){browserAlert('Restore failed',e.message||String(e));}
          }}
        ]);
      }catch(e){browserAlert('Restore failed',e.message)}
    };
    picker.click();
  }catch(e){browserAlert('Import failed',e.message)}
};
