const historyTrend=()=>{const now=new Date();return Array.from({length:6},(_,i)=>{const d=new Date(now.getFullYear(),now.getMonth()-5+i,1);const key=iso(d).slice(0,7);const amount=payments.filter(p=>typeof p.paid_at==='string'&&p.paid_at.slice(0,7)===key).reduce((a,p)=>a+Number(p.amount||0),0);return {label:d.toLocaleDateString('en-US',{month:'short'}),amount,key}})};
